'use strict';
(function(){
const J=MaisonJourney,esc=I.esc;let owner=null,shown=null;
function chances(){return `<span class="journey-lives" aria-label="${state.journey.chances} chances sur 3">${[0,1,2].map(i=>`<b class="${i<state.journey.chances?'':'spent'}">◆</b>`).join('')} <small>${state.journey.chances}/3 chances</small></span>`;}
function heading(index=state.journey.act,preview=false){const act=J.acts[index];return `<div class="journey-heading"><div><span class="eyebrow">ACTE ${index+1} · ${esc(act.name.toUpperCase())}</span><h2>${esc(act.title)}</h2></div>${chances()}</div><div class="journey-horizon">${J.acts.map((a,i)=>preview?`<button data-view-act="${i}" class="${i===index?'viewing':''}" aria-pressed="${i===index}">${i<state.journey.act?'✓':i+1} · ${a.short}${i>state.journey.act?' ◇':''}</button>`:`<span class="${i===index?'viewing':''}">${i<state.journey.act?'✓':i+1} · ${a.short}</span>`).join('')}</div>`;}
function summary(){const j=state.journey;if(!j)return '';const o=j.selected;return `<section class="journey-summary"><span class="eyebrow">LE PARCOURS · ACTE ${j.act+1}/4</span><strong>${j.status==='won'?'★ Reconnaissance mondiale':j.status==='lost'?'La tournée s’arrête':o?esc(o.name):'Choisir la prochaine destination'}</strong>${chances()}${o?`<small>Semaine ${o.week} · ${o.fans} spectateurs</small><p>${esc(o.rewardDescription)}</p>`:`<p>${j.history.length} show(s) résolu(s) · ${esc(J.currentAct(state).name)}.</p>`}${j.writingBonus?`<small>✎ ${j.writingBonus} bonus d’écriture en réserve</small>`:''}<button data-journey-open>Voir le parcours ↗</button></section>`;}
function routeCard(o,index,actIndex){const j=state.journey,current=actIndex===j.act,record=j.history.findLast(h=>(h.act||0)===actIndex&&h.stage===index),selected=current&&j.stage===index&&j.selected?.id===o.id,done=record?.destination.id===o.id,available=current&&j.status==='active'&&j.stage===index&&!j.selected&&!j.pendingReward&&!j.pendingArc&&!['offered','decision'].includes(j.encounter?.phase)&&!T.busy(state)&&state.tick>=j.routeReadyAt;return `<article class="route-card ${selected?'chosen':''} ${done?'completed':''}"><span class="route-icon">${o.icon}</span><h3>${esc(o.name)}</h3><div class="route-styles">${o.styles.map(g=>`<span>${I.genreIcon(g)}${esc(g)}</span>`).join('')}</div><p class="route-challenge">${esc(o.challenge)}</p><small class="route-difficulty">Résistance du public : ${o.resistance} %</small><div class="route-reward"><small>SI LE SHOW EST RÉUSSI</small><p>${esc(J.rewardText(o))}</p>${o.candidate?`<small>${o.candidate.traits.map(esc).join(' · ')}</small>`:''}</div>${available?`<button class="primary" data-route="${o.id}">Choisir cette destination →</button>`:`<span class="route-status">${done?(record.success?'✓ Réussi':'× Échoué'):selected?'✓ Destination choisie':actIndex>j.act?'Acte à débloquer':actIndex<j.act||index<j.stage?'Autre chemin':index>j.stage?'À venir':'Verrouillé'}</span>`}</article>`;}
function openMap(actIndex=state.journey.act){const j=state.journey;openDialog(`<div class="journey-dialog">${heading(actIndex,true)}<p class="journey-intro">Choisis le show et sa récompense à l’avance. Deux étapes, puis une finale la semaine suivante. ${actIndex>j.act?'Aperçu : dates estimées, acte encore verrouillé.':''}</p><div class="journey-map">${J.acts[actIndex].stages.map((_,i)=>`<section class="route-step ${actIndex===j.act&&i===j.stage?'current':''}"><div class="route-step-label">${i+1} · ${i===2?'SHOW FINAL':'EMBRANCHEMENT'}<span>S${J.stageWeek(state,i,actIndex)}</span></div>${J.options(state,i,actIndex).map(o=>routeCard(o,i,actIndex)).join('')}</section>`).join('')}</div><p class="tiny">À 0 chance, la tournée s’arrête. Une finale d’acte réussie rend 1 chance (maximum 3) et ouvre l’acte suivant. Une finale manquée se retente la semaine suivante. La finale mondiale remporte la partie.</p><button id="journeyClose" class="quiet">Retour à la maison</button></div>`);document.querySelectorAll('[data-view-act]').forEach(b=>b.onclick=()=>openMap(Number(b.dataset.viewAct)));document.querySelectorAll('[data-route]').forEach(b=>b.onclick=()=>{if(!J.choose(state,b.dataset.route))return;save();shown=null;closeDialog(true);render();});$('#journeyClose').onclick=()=>closeDialog(true);}
function reward(){const r=state.journey.pendingReward;if(!r)return;if(r.kind==='composition'){openDialog(`<div class="journey-dialog journey-event">${heading()}<span class="eyebrow">RÉSIDENCE D’ÉCRITURE · RÉCOMPENSE OBTENUE</span><h3>De nouvelles idées à rapporter à la maison</h3><p>${esc(r.title)}</p><div class="journey-event-effect">✎ +1 niveau à la prochaine nouvelle composition <small>Maximum 7 · ${state.journey.writingBonus} bonus en réserve · les chansons adoptées restent inchangées.</small></div><button id="ackWriting" class="primary">Retour à la maison →</button></div>`);$('#ackWriting').onclick=()=>{if(!J.acknowledgeWriting(state))return;save();shown=null;closeDialog(true);render();};return;}
 const exchange=r.kind==='exchange';openDialog(`<div class="journey-dialog">${heading()}<span class="eyebrow">${esc(r.title)}</span><h3>${exchange?'Une masterclasse pour affiner son jeu':'Une carte supplémentaire'}</h3><p>${exchange?'Quel musicien remplacera une carte par une des trois spéciales de son instrument ?':'Quel musicien recevra le choix de trois cartes spéciales ?'}</p><div class="journey-people">${state.people.map(p=>`<button data-claim="${p.id}">${I.portrait(p)}<strong>${I.icons[p.instrument]} ${esc(p.name)}</strong><small>${p.deck.length} cartes · ${esc(p.instrument)}</small></button>`).join('')}</div></div>`);document.querySelectorAll('[data-claim]').forEach(b=>b.onclick=()=>{if(!J.claimCard(state,b.dataset.claim))return;save();const e=state.music.pending.find(e=>e.journeyId===r.id);if(e)window.MaisonMusicUI.showStory(e.id);render();});}
function milestone(){const j=state.journey,e=j.pendingArc;if(!e)return;openDialog(`<div class="journey-dialog journey-event">${heading()}<span class="eyebrow">ACTE ${e.completedAct+1} TERMINÉ</span><h2>Un nouveau public vous attend.</h2><p>Vous avez conquis la ${esc(J.acts[e.completedAct].name.toLowerCase())}. Votre groupe poursuit maintenant son parcours vers la ${esc(J.acts[e.nextAct].name.toLowerCase())}.</p><div class="journey-event-effect">◆ +1 chance, jusqu’à 3 <small>${j.chances}/3 chances · prochain show en semaine ${j.nextWeek}.</small></div><p>De nouvelles destinations et leurs récompenses sont disponibles. Les musiciens, les chansons et les paquets vous accompagnent.</p><button id="continueAct" class="primary">Découvrir le prochain acte →</button></div>`);$('#continueAct').onclick=()=>{if(!J.acknowledgeArc(state))return;save();shown=null;openMap();render();};}
function encounter(){const e=state.journey.encounter;if(!e)return;const p=e.candidate,decision=e.phase==='decision';openDialog(`<div class="journey-dialog">${heading()}<span class="eyebrow">${decision?'MINUIT · LE BILAN DE L’ESSAI':'RENCONTRE GAGNÉE SUR LE PARCOURS'}</span><div class="journey-candidate">${I.portrait(p)}<div><h3>${I.icons[p.instrument]} ${esc(p.name)}</h3><strong>${esc(p.instrument)} · ${esc(p.style)}</strong><p>${p.traits.map(esc).join(' · ')}</p></div></div>${decision?`<p>${e.verdict.candidate?`${esc(p.name)} souhaite rester dans le groupe.`:`${esc(p.name)} n’a pas trouvé assez d’affinités et préfère repartir.`}</p><div class="journey-votes">${e.votes.map(v=>`<p><b>${v.yes?'✓':'↪'} ${esc(state.people.find(p=>p.id===v.id)?.name)}</b> · ${esc(v.reason)}</p>`).join('')}</div><p>${e.verdict.band?'La majorité du groupe est favorable.':'Le groupe ne réunit pas une majorité favorable.'}</p><div class="choice-row">${e.verdict.band&&e.verdict.candidate?'<button class="primary" id="joinVisitor">L’intégrer au groupe</button>':''}<button id="declineVisitor">${e.verdict.band&&e.verdict.candidate?'Décliner':'Lui souhaiter bonne route'}</button></div>`:`<p>Une semaine pour se découvrir : café, échanges et jam d’observation dans la maison. Ses contacts et les affinités musicales guideront les avis. Le groupe et ${esc(p.name)} devront être partants.</p><p class="hint">Invité pendant l’essai : ne participe pas encore au deck des shows. Il suit les répétitions et reste dans les pièces communes. À minuit, vous décidez avant le choix de nuit.</p><div class="choice-row"><button class="primary" id="trialVisitor">L’inviter pour une semaine</button><button id="declineVisitor">Décliner la rencontre</button></div>`}</div>`);const act=c=>{if(!J.meetingChoice(state,c))return;save();shown=null;closeDialog(true);render();};if($('#trialVisitor'))$('#trialVisitor').onclick=()=>act('trial');if($('#joinVisitor'))$('#joinVisitor').onclick=()=>act('join');$('#declineVisitor').onclick=()=>act('decline');}
function finale(){const j=state.journey;openDialog(`<div class="journey-dialog">${heading()}<span class="eyebrow">${j.status==='won'?'VICTOIRE MONDIALE':'FIN DE PARTIE'}</span><h2>${j.status==='won'?'Du garage aux scènes du monde.':'Cette tournée s’arrête ici.'}</h2><p>${j.status==='won'?'Le concert des horizons est réussi : votre groupe est reconnu mondialement. Les quatre actes sont terminés.':'Vos chances sont épuisées. Une autre formation et un autre parcours vous attendent.'}</p><div class="journey-bilan"><b>${j.history.filter(h=>h.success).length} shows réussis</b><b>${state.music.songs.filter(M.ready).length} chansons prêtes</b><b>${state.people.length} musiciens</b></div><div class="journey-history">${J.acts.map((act,i)=>{const h=j.history.filter(h=>(h.act||0)===i);return `<p>${h.some(h=>h.stage===2&&h.success)?'✓':'◇'} <strong>${esc(act.name)}</strong><small>${h.filter(h=>h.success).length}/${h.length} shows réussis${!h.length?' · non atteinte':''}</small></p>`;}).join('')}</div><p class="tiny">La simulation est arrêtée. Tu peux consulter la maison ou relancer une partie.</p><div class="choice-row"><button id="journeyHome" class="primary">Retour à l’accueil</button><button id="journeyInspect">Consulter la maison</button></div></div>`);$('#journeyHome').onclick=()=>{closeDialog(false);$('#homeButton').click();};$('#journeyInspect').onclick=()=>closeDialog(false);}
function open(){const j=J.init(state);if(j.status!=='active')return finale();if(j.pendingArc&&state.tick>=j.routeReadyAt&&!T.busy(state))return milestone();if(j.pendingReward&&state.tick>=j.routeReadyAt&&!T.busy(state))return reward();if(['offered','decision'].includes(j.encounter?.phase)&&state.tick>=j.routeReadyAt&&!T.busy(state))return encounter();openMap();}
function maybeShow(){if(owner!==state){owner=state;shown=null;}if(window.homeOpen||$('#dialog').open||T.busy(state)||state.calendar.wake||(state.calendar.pending&&state.journey?.encounter?.phase!=='decision'))return false;const j=state.journey;if(!j||!J.blocked(state))return false;const key=j.status!=='active'?j.status:j.pendingArc?'arc-'+j.pendingArc.id:j.pendingReward?'reward-'+j.pendingReward.id:['offered','decision'].includes(j.encounter?.phase)?j.encounter.id+'-'+j.encounter.phase:'route-'+j.act+'-'+j.stage+'-'+j.nextWeek;if(shown===key)return false;shown=key;open();return true;}
function render(){const j=state.journey;if(!j)return;$('#invite').textContent='↗ Parcours';$('#invite').title='Destinations, récompenses et rencontres';$('#invite').disabled=false;maybeShow();}
window.MaisonJourneyUI={render,summary,open,maybeShow};
})();
